Pipeline pipeline = Pipeline.create(options);

pipeline
    .apply(
        "Read company ids",
        TextIO.read().from(inputPath)
    )
    .apply(
        "Parse company ids",
        ParDo.of(new ParseCompanyIdFn())
    )
    .apply(
        "Load company data",
        ParDo.of(new LoadCompanyDataFn())
    )
    .apply(
        "Write results",
        ParDo.of(new WriteCoverageSnapshotFn())
    );

pipeline.run();
